      SUBROUTINE ARGUECC     TRANSFER FROM DUMMY ARGUMENT TO ELEMENT OR BEAM SUBLINECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM24B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLESC      INTEGER          IDATA, J, NARG, NUMA      EXTERNAL         IDATACC-----------------------------------------------------------------      J = JDEF      GO TO (100,100,300,300), JC  100 IF (.NOT. ATWORK) GO TO 400      IF (J .EQ. 1 .AND. NDIF .EQ. 1) GO TO 200      IF (J .EQ. 1 .AND. NDIF .EQ. -1) GO TO 250      IF (J .EQ. 2 .AND. NDIF .EQ. 1) GO TO 250      IF (J .EQ. 2 .AND. NDIF .EQ. -1) GO TO 200CC     BEGINNING OF ACTUAL ARGUMENTC     STEP THROUGH WITHOUT EXECUTION, WAIT UNTIL CALLED BY DUMMYC  200 NUM = NUM + NDIF      I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .NE. 32) GO TO 200      NEND = IDATA(I+1)      IF (NEND .NE. 2) GO TO 200      NARG = IDATA(I+2)      IF (NARG .NE. NADDEF(1)) GO TO 200      GO TO 400CC     END OF ACTUAL ARGUMENT, TRANSFER BACK TO DUMMYC  250 NUM = NUC(NULEV)      NDIF = NDIF*NUS(NULEV)      NULEV = NULEV - 1      IF (NULEV .LT. 0) THEN        WRITE (NOUT,9002) NULEV 9002   FORMAT (' *** ERROR *** ARGUMENT LEVEL = ',I5)        FLUSHL = .TRUE.        GO TO 400      ENDIF      GO TO 400CC      ENCOUNTER DUMMY ARGUMENT, TRANSFER TO ACTUAL ARGUMENTC  300 IF (NUM .EQ. NUSE) ATWORK = .TRUE.      IF (.NOT. ATWORK) GO TO 400      NUMA = NUM      NUM = NDC(NDLEV-NULEV)      NULEV = NULEV + 1      IF (NULEV .GT. 10) THEN        WRITE (NOUT,9003) NULEV 9003   FORMAT (' *** ERROR ***, ARGUMENT LEVEL = ',I5)        FLUSHL = .TRUE.        GO TO 400      ENDIF      NUC(NULEV) = NUMA      IF (J .EQ. 3) NUS(NULEV) = 1      IF (J .EQ. 4) NUS(NULEV) = -1      NDIF = NDIF*NUS(NULEV)CC     STEP THROUGH ARGUMENTS UNTIL CORRECT ONE IS ENCOUNTEREDC  310 NUM = NUM + 1      I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .NE. 32) GO TO 310      NEND = IDATA(I+1)      IF (NDIF .EQ. 1 .AND. NEND .NE. 1) GO TO 310      IF (NDIF .EQ. -1 .AND. NEND .NE. 2) GO TO 310      NARG = IDATA(I+2)      IF (NARG .NE. NADDEF(1)) GO TO 310C  400 CONTINUE      RETURN      END